ScheduledTasks: FC<ScheduledTasksProps> = ({
  labels,
  onCreateClick,
  searchQuery,
  onSearchQueryChange,
  sortKey,
  onSortChange,
  items,
  isLoading = false,
  error,
  onRetry,
  hasMore = false,
  isLoadingMore = false,
  skeletonCount = 6,
  onLoadMore,
  onCardClick,
  banner,
  styles: scheduledTasksStyles,
}) => {
  const { colors, typography } = scheduledTasksStyles ?? {};
  const titleClassName = typography?.titleClassName ?? 'dial-h1-text';
  const subtitleClassName = typography?.subtitleClassName ?? 'dial-body-text';
  const cssVars = buildCssVars({
    '--st-bg': colors?.background,
    '--st-subtitle-text': colors?.subtitleText,
    '--st-sort-text': colors?.sortButtonText,
  });

  const handleSearchChange = (value?: string) => {
    onSearchQueryChange(value ?? '');
  };

  const [isSortMenuOpen, setIsSortMenuOpen] = useState(false);
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const sortControlRef = useRef<HTMLDivElement | null>(null);

  const handleSearchFocus = useCallback(() => {
    setIsSearchFocused(true);
  }, []);

  const handleSearchBlur = useCallback(() => {
    setIsSearchFocused(false);
  }, []);

  /*
   * When the search is focused at phone widths (`.sortControlHidden` in the
   * SCSS), the sort trigger is display:none'd while its portaled popup can
   * stay open — the kit's Dropdown closes on outside pointer press only, not
   * on keyboard focus. Close the menu exactly in that case, detected from the
   * DOM rather than a second copy of the px cutoff, so from 768px up — where
   * the control never hides — search focus leaves an open sort menu alone.
   */
  useLayoutEffect(() => {
    const sortControl = sortControlRef.current;
    if (
      isSearchFocused &&
      isSortMenuOpen &&
      sortControl != null &&
      sortControl.offsetParent == null
    ) {
      setIsSortMenuOpen(false);
    }
  }, [isSearchFocused, isSortMenuOpen]);

  /* Falls back to the control's own name so the trigger is never a button with
   * no accessible name, which is what an unrecognised sortKey would produce —
   * the kit's `Button` derives its `aria-label` from `label` and overrides any
   * the caller passes, so the visible label is the only name available. */
  const activeSortLabel =
    labels.sortOptions.find((option) => option.value === sortKey)?.label ??
    labels.sortLabel;

  /*
   * The host passes the values alone; the marking and the click belong here,
   * so the trigger and the menu cannot disagree about which order is applied.
   */
  const sortItems = useMemo<DropdownItem[]>(
    () =>
      labels.sortOptions.map((option) => ({
        key: option.value,
        label: option.label,
        mark: MenuItemMark.Check,
        checked: option.value === sortKey,
        onClick: () => onSortChange(option.value as ScheduledTasksSortKey),
      })),
    [labels.sortOptions, sortKey, onSortChange],
  );

  const statusMessage = getStatusMessage(
    isLoading,
    isLoadingMore,
    Boolean(error),
    items.length,
    searchQuery.trim().length > 0,
    labels,
  );

  const sentinelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel || !onLoadMore) return;

    const scrollRoot = findScrollParent(sentinel.parentElement);
    if (!scrollRoot) return;

    const checkVisibility = () => {
      if (isLoadingMore || isLoading || !hasMore) return;
      const rootRect = scrollRoot.getBoundingClientRect();
      const sentinelRect = sentinel.getBoundingClientRect();
      if (
        sentinelRect.top < rootRect.bottom &&
        sentinelRect.bottom > rootRect.top
      ) {
        onLoadMore();
      }
    };

    scrollRoot.addEventListener('scroll', checkVisibility, { passive: true });
    checkVisibility();
    return () => scrollRoot.removeEventListener('scroll', checkVisibility);
    /*
     * `items.length` is intentionally not a dependency here: whenever a page
     * finishes loading and `items` grows, `isLoadingMore` (or `isLoading` for
     * the first page) flips in the same render, which already re-runs this
     * effect and re-checks the newly taller layout. Listing `items.length`
     * too would only force a redundant teardown/re-attach of the listener.
     */
  }, [hasMore, isLoadingMore, isLoading, onLoadMore]);

  const renderContent = () => {
    if (isLoading) {
      return <Spinner />;
    }

    if (error) {
      return (
        <div className="flex flex-col items-center gap-3">
          <p className={mergeClasses(subtitleClassName, styles.subtitle)}>
            {labels.errorLabel}
          </p>
          <GhostButton label={labels.retryLabel} onClick={onRetry} />
        </div>
      );
    }

    if (items.length === 0) {
      if (searchQuery.trim()) {
        return (
          <p className={mergeClasses(subtitleClassName, styles.subtitle)}>
            {labels.noResultsLabel}
          </p>
        );
      }
      return <PanelEmptyState label={labels.emptyStateLabel} />;
    }

    return (
      <div className="flex w-full flex-col gap-6">
        <ScheduledTaskCardGrid
          items={items}
          searchQuery={searchQuery}
          onCardClick={onCardClick}
          labels={labels.cardLabels}
          trailingSkeletonCount={isLoadingMore ? skeletonCount : 0}
          skeletonStyles={{
            colors: { skeletonColor: colors?.skeletonColor },
          }}
        />

        <div ref={sentinelRef} aria-hidden className="h-px w-full" />
      </div>
    );
  };

  const isCentered = isLoading || Boolean(error) || items.length === 0;

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'flex h-full w-full flex-col gap-6 overflow-y-auto px-8 py-4',
        styles.container,
      )}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0 gap-2">
          <h1 className={mergeClasses('truncate', titleClassName)}>
            {labels.title}
          </h1>
          <p
            className={mergeClasses('mt-1', subtitleClassName, styles.subtitle)}
          >
            {labels.subtitle}
          </p>
        </div>

        <PrimaryButton
          /* The kit wraps `label` in its own span (carrying `textClassName`)
           * that stays a flex item even when its content is hidden — the gap
           * then pushes the icon off-center. Hiding the wrapper span itself
           * below the desktop breakpoint removes the flex item entirely, so
           * the plus icon alone carries the action, centered. `aria-label`
           * keeps the accessible name stable at every width. */
          label={labels.createButtonLabel}
          textClassName="hidden desktop:inline"
          aria-label={labels.createButtonLabel}
          iconBefore={
            <IconPlus
              size={DIAL_ICON_SIZE.SM}
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          }
          onClick={onCreateClick}
          className={mergeClasses('shrink-0', styles.createButton)}
        />
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <div role="search" className="flex-1">
          <Search
            value={searchQuery}
            onChange={handleSearchChange}
            placeholder={labels.searchPlaceholder}
            clearLabel={labels.clearSearchLabel}
            aria-label={labels.searchAriaLabel}
            size={ElementSize.Large}
            onFocus={handleSearchFocus}
            onBlur={handleSearchBlur}
          />
        </div>
        {labels.sortOptions.length > 0 && (
          /* The trigger shows the applied order and the menu marks it with the
             design's trailing check. */

          /* While the search is focused at phone widths (<768px, see
           * `.sortControlHidden`) the sort control is hidden and the search
           * (flex-1) expands to the full row; from 768px up both controls
           * stay visible regardless of focus. */
          <div
            ref={sortControlRef}
            className={mergeClasses(
              isSearchFocused && styles.sortControlHidden,
            )}
          >
            <ButtonDropdown
              items={sortItems}
              label={activeSortLabel}
              variant={ButtonVariant.Primary}
              appearance={ButtonAppearance.Ghost}
              className={styles.sortButton}
            />
          </div>
        )}
      </div>

      {banner}

      <span role="status" aria-live="polite" className="sr-only">
        {statusMessage}
      </span>

      <div
        className={mergeClasses(
          'mx-auto flex size-full w-full max-w-[1180px] flex-col',
          isCentered && 'items-center justify-center',
        )}
      >
        {renderContent()}
      </div>
    </div>
  );
}

export interface ScheduledTasksProps {
  /** Localized labels. */
  labels: ScheduledTasksLabels;
  /** Called when the user activates the primary "create task" action. */
  onCreateClick: () => void;
  /** Current value of the toolbar search input. */
  searchQuery: string;
  /** Called when the toolbar search input value changes. */
  onSearchQueryChange: (query: string) => void;
  /** Key of the currently selected sort option. */
  sortKey: ScheduledTasksSortKey;
  /** Called when the user selects a different sort option. */
  onSortChange: (key: ScheduledTasksSortKey) => void;
  /** Tasks to render as cards, already search-matched and sorted server-side; rendered in the order received. */
  items: ScheduledTaskItem[];
  /** When `true`, the content region shows a loading spinner instead of `items`. Defaults to `false`. */
  isLoading?: boolean;
  /** When set, the content region shows an error message and retry action instead of `items`. */
  error?: Error | null;
  /** Called when the user activates the retry action shown alongside `error`. */
  onRetry?: () => void;
  /** Whether another page of `items` is available beyond what has been loaded so far. Defaults to `false`. */
  hasMore?: boolean;
  /** When `true`, `skeletonCount` placeholder cards render below the loaded cards while the next page is fetched. Defaults to `false`. */
  isLoadingMore?: boolean;
  /** Number of placeholder cards shown while `isLoadingMore` is `true`. Defaults to `6`. */
  skeletonCount?: number;
  /** Called when the trailing scroll sentinel becomes visible and `hasMore && !isLoadingMore && !isLoading`. */
  onLoadMore?: () => void;
  /** Called with a task id when the user activates a card's body. Omit to render cards with no added interactive root semantics. */
  onCardClick?: (id: string) => void;
  /** Content rendered between the search/sort toolbar and the content region (e.g. a status banner). Renders nothing when omitted. */
  banner?: ReactNode;
  /** Style overrides. */
  styles?: ScheduledTasksStyles;
}

export interface ScheduledTasksLabels {
  /** Page title, e.g. "Scheduled tasks". */
  title: string;
  /** One-line description shown beneath the title. */
  subtitle: string;
  /** Label for the primary "create task" action button. */
  createButtonLabel: string;
  /** Placeholder text for the toolbar search input. */
  searchPlaceholder: string;
  /** Accessible label for the toolbar search input. */
  searchAriaLabel: string;
  /** Accessible label for the toolbar search input's clear action. */
  clearSearchLabel: string;
  /** The sort control's own name, prepended to its accessible name. */
  sortLabel: string;
  /**
   * Values the sort menu lists; each `value` is a `ScheduledTasksSortKey`.
   * Only the values — the component owns which one is marked as applied and
   * what a click does.
   */
  sortOptions: SelectOption[];
  /** Message shown when the fetched task list is empty. */
  emptyStateLabel: string;
  /** Message shown when `searchQuery` filters every task out. */
  noResultsLabel: string;
  /** Message shown alongside the retry action when `error` is set. */
  errorLabel: string;
  /** Label for the retry action shown when `error` is set. */
  retryLabel: string;
  /** Announced via `aria-live` while a load-more fetch is in flight (`isLoadingMore`). Optional — no announcement is made when omitted. */
  loadingMoreLabel?: string;
  /** Localized labels forwarded as-is to every card in the grid. */
  cardLabels?: ScheduledTaskCardGridLabels;
}

export interface ScheduledTasksStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: ScheduledTasksColors;
  /** Typography class overrides. */
  typography?: ScheduledTasksTypography;
}

export interface ScheduledTasksColors {
  /** Root container background. Fallback: `--bg-layer-base`. */
  background?: string;
  /** Subtitle and status-message (empty/no-results/error) text color. Fallback: `--text-secondary`. */
  subtitleText?: string;
  /** Sort control label/icon color. Fallback: `--text-accent`. */
  sortButtonText?: string;
  /** Background color of the load-more placeholder skeleton bars. Fallback: `--bg-control-disable-primary`. */
  skeletonColor?: string;
}

export interface ScheduledTasksTypography {
  /** CSS class applied to the title. Defaults to `'dial-h1-text'`. */
  titleClassName?: string;
  /** CSS class applied to the subtitle and status messages (empty/no-results/error). Defaults to `'dial-body-text'`. */
  subtitleClassName?: string;
}

ScheduledTaskCard: FC<ScheduledTaskCardProps> = ({
  item,
  searchQuery = '',
  onCardClick,
  labels,
  styles: cardStyles,
  className,
}) => {
  const newBadgeLabel = labels?.newBadgeLabel ?? 'NEW';
  const pausedBadgeLabel = labels?.pausedBadgeLabel ?? 'Paused';

  const { colors, typography } = cardStyles ?? {};
  const titleClassName = typography?.titleClassName ?? 'dial-body-semi-text';
  const descriptionClassName =
    typography?.descriptionClassName ?? 'dial-small-text';
  const descriptionSizeClassName =
    typography?.descriptionSizeClassName ?? 'dial-tiny-text';
  const scheduleLabelClassName =
    typography?.scheduleLabelClassName ?? 'dial-tiny-text';
  const locationLabelClassName =
    typography?.locationLabelClassName ?? 'dial-tiny-text';
  const locationLeafClassName =
    typography?.locationLeafClassName ?? 'dial-tiny-semi-text';
  const newBadgeClassName =
    typography?.newBadgeClassName ?? 'dial-tiny-semi-text';
  const pausedBadgeClassName =
    typography?.pausedBadgeClassName ?? 'dial-tiny-text';
  const cssVars = buildCssVars({
    '--stc-title-text': colors?.titleText,
    '--stc-desc-text': colors?.descriptionText,
    '--stc-pill-bg': colors?.schedulePillBackground,
    '--stc-pill-border': colors?.schedulePillBorder,
    '--stc-schedule-label-text': colors?.scheduleLabelText,
    '--stc-location-label-text': colors?.locationLabelText,
    '--stc-location-leaf-text': colors?.locationLeafText,
    '--stc-new-badge-bg': colors?.newBadgeBackground,
    '--stc-new-badge-text': colors?.newBadgeText,
    '--stc-location-divider-border': colors?.locationDividerBorder,
    '--stc-paused-bg': colors?.pausedBadgeBackground,
    '--stc-paused-border': colors?.pausedBadgeBorder,
    '--stc-paused-text': colors?.pausedBadgeText,
  });

  const cardClickProps = onCardClick
    ? {
        tabIndex: 0,
        onClick: () => onCardClick(item.id),
        onKeyDown: (event: KeyboardEvent) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            onCardClick(item.id);
          }
        },
      }
    : {};

  return (
    <CardShell
      role={onCardClick ? 'button' : 'group'}
      aria-label={item.displayName}
      style={cssVars}
      className={mergeClasses(
        'h-[232px]',
        onCardClick && 'cursor-pointer',
        className,
        SCHEDULED_TASKS_CLASS.card,
      )}
      {...cardClickProps}
    >
      <div className="flex min-w-0 shrink-0 items-center gap-2">
        <Highlight
          text={item.displayName}
          query={searchQuery}
          maxLines={1}
          className={mergeClasses(titleClassName, styles.title)}
        />
        {item.isNew && (
          <span
            className={mergeClasses(
              'shrink-0 rounded-full px-2 py-0.5',
              newBadgeClassName,
              styles.newBadge,
            )}
          >
            {newBadgeLabel}
          </span>
        )}
      </div>

      {item.descriptionPreview && (
        <p
          className={mergeClasses(
            'line-clamp-4 min-h-0 flex-1 overflow-hidden',
            descriptionSizeClassName,
            descriptionClassName,
            styles.description,
          )}
        >
          {item.descriptionPreview}
        </p>
      )}

      <div className="mt-auto flex shrink-0 flex-col gap-3">
        <div className="flex min-h-[28px] items-center">
          {item.isActive === false ? (
            <span
              className={mergeClasses(
                'inline-flex items-center gap-1.5 rounded-full border px-2 py-1',
                styles.pausedPill,
                pausedBadgeClassName,
                styles.pausedLabel,
              )}
            >
              <IconPlayerPause
                size={DIAL_ICON_SIZE.SM}
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
              {pausedBadgeLabel}
            </span>
          ) : (
            <span
              className={mergeClasses(
                'inline-block rounded-lg border px-2 py-1',
                styles.schedulePill,
                scheduleLabelClassName,
                styles.scheduleLabel,
              )}
            >
              {item.scheduleLabel}
            </span>
          )}
        </div>

        {item.locationSegments && item.locationSegments.length > 0 && (
          <FolderPath
            segments={item.locationSegments}
            labelClassName={mergeClasses(
              locationLabelClassName,
              styles.locationLabel,
            )}
            leafClassName={mergeClasses(
              locationLeafClassName,
              styles.locationLeaf,
            )}
            className={mergeClasses('pt-3', styles.locationDivider)}
          />
        )}
      </div>
    </CardShell>
  );
}

