export enum ScheduledTaskRepeat {
  /** Task runs once at the date/time specified by `runAt`. */
  OneTime = 'oneTime',
  /** Task runs every hour, at the start of the hour. */
  Hourly = 'hourly',
  /** Task runs every day at the specified `time`. */
  Daily = 'daily',
  /** Task runs every week on `dayOfWeek` at the specified `time`. */
  Weekly = 'weekly',
  /** Task runs every month on `dayOfMonth` at the specified `time`. */
  Monthly = 'monthly',
}

ScheduledTaskDetailView: FC<ScheduledTaskDetailViewProps> = ({
  labels,
  onBack,
  onEdit,
  onDelete,
  isDeleting = false,
  isDeleted = false,
  isActive,
  isActiveUpdating = false,
  isActiveDisabled = false,
  onActiveChange,
  displayName,
  isLoading = false,
  error,
  onRetry,
  description,
  modelLabel,
  repeatsLabel,
  activeWindowLabel,
  nextRunLabel,
  instructionsMarkdown,
  renderInstructions,
  runs,
  runsIsLoading = false,
  runsIsLoadingMore = false,
  runsSkeletonCount = 6,
  runsError,
  onRunsRetry,
  runsHasMore = false,
  onRunsLoadMore,
  onRunClick,
  styles: viewStyles,
}) => {
  const { colors, typography } = viewStyles ?? {};
  const titleClassName = typography?.titleClassName ?? 'dial-h2-text';
  const sectionTitleClassName =
    typography?.sectionTitleClassName ?? 'dial-body-semi-text';
  const fieldLabelClassName =
    typography?.fieldLabelClassName ?? 'dial-tiny-text';
  const fieldValueClassName =
    typography?.fieldValueClassName ?? 'dial-small-text';
  const runTimestampClassName =
    typography?.runTimestampClassName ?? 'dial-small-text';

  const cssVars = buildCssVars({
    '--stdv-bg': colors?.background,
    '--stdv-header-border': colors?.headerBorder,
    '--stdv-details-border': colors?.detailsColumnBorder,
    '--stdv-subtitle-text': colors?.subtitleText,
    '--stdv-history-bg': colors?.historyCardBackground,
  });

  const isMobile = useIsMobile();
  /*
   * Keyed as a plain string so the kit's `onTabChange(tabId: string)` maps
   * straight onto the state setter; the only ids ever stored are the
   * `ScheduledTaskDetailTab` values. Held here — not under the mobile-only
   * branch — so the selection survives a viewport resize across the
   * breakpoint instead of resetting.
   */
  const [activeTabId, setActiveTabId] = useState<string>(
    ScheduledTaskDetailTab.Details,
  );

  const detailTabs: TabItem[] = [
    { id: ScheduledTaskDetailTab.Details, label: labels.detailsTitle },
    {
      id: ScheduledTaskDetailTab.Configuration,
      label: labels.configurationTitle,
    },
    { id: ScheduledTaskDetailTab.History, label: labels.historyTitle },
  ];
  const activeTabLabel =
    detailTabs.find((tab) => tab.id === activeTabId)?.label ??
    labels.detailsTitle;

  /*
   * The section elements are built once and composed by whichever layout the
   * current viewport mounts, so section content cannot drift between the
   * mobile/tab and desktop/column presentations. Only the History section
   * differs by context (card vs flow chrome), so it's a builder.
   */
  const detailsSection = (
    <ScheduledTaskDetailsSection
      labels={{
        descriptionLabel: labels.descriptionLabel,
        modelLabel: labels.modelLabel,
        repeatsLabel: labels.repeatsLabel,
        activeWindowLabel: labels.activeWindowLabel,
      }}
      description={description}
      modelLabel={modelLabel}
      repeatsLabel={repeatsLabel}
      activeWindowLabel={activeWindowLabel}
      fieldLabelClassName={fieldLabelClassName}
      fieldValueClassName={fieldValueClassName}
    />
  );

  const configurationSection = (
    <ScheduledTaskConfigurationSection
      instructionsLabel={labels.instructionsLabel}
      instructionsMarkdown={instructionsMarkdown}
      renderInstructions={renderInstructions}
      fieldLabelClassName={fieldLabelClassName}
    />
  );

  const buildHistorySection = (
    variant: ScheduledTaskHistorySectionVariant,
  ): ReactNode => (
    <ScheduledTaskHistorySection
      variant={variant}
      labels={{
        historyTitle: labels.historyTitle,
        historyEmptyLabel: labels.historyEmptyLabel,
        historyErrorLabel: labels.historyErrorLabel,
        historyRetryLabel: labels.historyRetryLabel,
        historyLoadingMoreLabel: labels.historyLoadingMoreLabel,
        historyShowMoreLabel: labels.historyShowMoreLabel,
        runStatusLabels: labels.runStatusLabels,
        unreadIndicatorLabel: labels.unreadIndicatorLabel,
      }}
      nextRunLabel={nextRunLabel}
      items={runs}
      isLoading={runsIsLoading}
      isLoadingMore={runsIsLoadingMore}
      skeletonCount={runsSkeletonCount}
      error={runsError}
      onRetry={onRunsRetry}
      hasMore={runsHasMore}
      onLoadMore={onRunsLoadMore}
      onRunClick={onRunClick}
      runTimestampClassName={runTimestampClassName}
      sectionTitleClassName={sectionTitleClassName}
      colors={colors}
    />
  );

  /*
   * Exactly one panel renders at a time. The tab row replaces the section
   * titles below the desktop breakpoint, so the panels carry no headings of
   * their own — the tab is the section's accessible name.
   */
  const renderActiveTabPanel = (): ReactNode => {
    if (activeTabId === ScheduledTaskDetailTab.Configuration) {
      return configurationSection;
    }
    if (activeTabId === ScheduledTaskDetailTab.History) {
      return buildHistorySection(ScheduledTaskHistorySectionVariant.Flow);
    }
    return detailsSection;
  };

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'flex h-full w-full flex-col overflow-y-auto',
        styles.container,
      )}
    >
      <div
        className={mergeClasses(
          'flex h-16 shrink-0 items-center justify-between gap-2 border-t px-8 desktop:border-b desktop:border-t-0',
          styles.header,
        )}
      >
        <div className="flex min-w-0 items-center gap-2">
          <GhostIconButton
            icon={
              <IconArrowLeft
                size={DIAL_ICON_SIZE.LG}
                className="rtl:scale-x-[-1]"
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
            }
            aria-label={labels.backAriaLabel}
            onClick={onBack}
          />
          {/*
           * Hidden below the desktop breakpoint, where the standalone title
           * row after the header renders its own copy — exactly one copy of
           * the title is visible at any width.
           */}
          <h1
            className={mergeClasses(
              'hidden truncate desktop:block',
              titleClassName,
            )}
          >
            {displayName}
          </h1>
          {isDeleted && (
            <span
              className={mergeClasses(
                'hidden shrink-0 desktop:inline',
                fieldValueClassName,
                styles.subtitleText,
              )}
            >
              {labels.deletedStateLabel}
            </span>
          )}
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {!isDeleted && isActive !== undefined && (
            <Switch
              id="scheduled-task-active-switch"
              labelProps={{ label: labels.activeStatusLabel }}
              isOn={isActive}
              disabled={isActiveUpdating || isActiveDisabled || isDeleting}
              onChange={(value) => onActiveChange?.(value)}
            />
          )}

          {!isDeleted && onDelete && (
            <GhostButton
              variant={ButtonVariant.Danger}
              label={labels.deleteButtonLabel}
              iconBefore={
                <IconTrashX
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              onClick={onDelete}
              disabled={isDeleting}
              className="shrink-0"
            />
          )}

          {!isDeleted && onEdit && (
            <NeutralButton
              label={labels.editButtonLabel}
              iconBefore={
                <IconPencilMinus
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              onClick={onEdit}
              disabled={isDeleting}
              className="shrink-0"
            />
          )}
        </div>
      </div>

      {/*
       * Standalone title row, visible only below the desktop breakpoint
       * (mobile and tablet), where the in-header title is hidden — exactly
       * one copy of the title is visible at any width.
       */}
      <div className="flex min-w-0 items-center gap-2 px-8 py-3 desktop:hidden">
        <h1 className={mergeClasses('truncate', titleClassName)}>
          {displayName}
        </h1>
        {isDeleted && (
          <span
            className={mergeClasses(
              'shrink-0',
              fieldValueClassName,
              styles.subtitleText,
            )}
          >
            {labels.deletedStateLabel}
          </span>
        )}
      </div>

      {labels.activeStatusAnnouncement != null && (
        <span role="status" aria-live="polite" className="sr-only">
          {labels.activeStatusAnnouncement}
        </span>
      )}

      {isLoading && (
        <div className="flex flex-1 items-center justify-center">
          <Spinner />
        </div>
      )}

      {!isLoading && error && (
        <div className="flex flex-1 flex-col items-center justify-center gap-3">
          <p className={mergeClasses(fieldValueClassName, styles.subtitleText)}>
            {labels.errorLabel}
          </p>
          <GhostButton label={labels.retryLabel} onClick={onRetry} />
        </div>
      )}

      {!isLoading &&
        !error &&
        (isMobile ? (
          <div className="flex flex-1 flex-col">
            <Tabs
              ariaLabel={labels.tabsAriaLabel ?? 'Scheduled task sections'}
              className="px-8"
              tabs={detailTabs}
              activeTabId={activeTabId}
              onTabChange={setActiveTabId}
            />
            {/*
             * One panel renders at a time. Its accessible name comes from the
             * active tab's label — the kit's tab elements expose no
             * referenceable ids for `aria-labelledby`.
             */}
            <div
              role="tabpanel"
              aria-label={activeTabLabel}
              className="flex flex-1 flex-col gap-5 px-8 py-6"
            >
              {renderActiveTabPanel()}
            </div>
          </div>
        ) : (
          <div className="flex flex-1 flex-col desktop:flex-row">
            <div
              role="group"
              aria-label={labels.detailsTitle}
              className={mergeClasses(
                'flex w-full flex-col gap-5 border-e px-8 py-6 desktop:w-[360px] desktop:shrink-0',
                styles.detailsColumn,
              )}
            >
              <h2 className={sectionTitleClassName}>{labels.detailsTitle}</h2>
              {detailsSection}
            </div>

            <div className="flex w-full min-w-0 flex-1 flex-col gap-5 px-8 py-6">
              <h2 className={sectionTitleClassName}>
                {labels.configurationTitle}
              </h2>
              {configurationSection}
            </div>

            <div className="flex w-full justify-center p-6 desktop:w-auto desktop:items-start">
              {buildHistorySection(ScheduledTaskHistorySectionVariant.Card)}
            </div>
          </div>
        ))}
    </div>
  );
}

export interface ScheduledTaskDetailViewProps {
  /** Localized labels. */
  labels: ScheduledTaskDetailViewLabels;
  /** Called when the user activates the back-navigation control. */
  onBack: () => void;
  /** Called when the user activates the header's Edit action. When omitted, no Edit action renders. Suppressed while `isDeleted` is `true`. */
  onEdit?: () => void;
  /** Called when the user activates the header's destructive Delete action. When omitted, no Delete action renders. Suppressed while `isDeleted` is `true`. The component opens no dialog and performs no network call itself. */
  onDelete?: () => void;
  /** When `true`, the Delete action, Edit action, and Active switch render disabled rather than being removed. Defaults to `false`. */
  isDeleting?: boolean;
  /** When `true`, the header renders a read-only deleted-state indicator instead of the Delete, Edit, and Active controls, regardless of whether `onDelete`/`onEdit`/`isActive` are supplied. Defaults to `false`. */
  isDeleted?: boolean;
  /** Whether the schedule is currently active (resumed) or paused. When `undefined`, the Active switch does not render. Suppressed while `isDeleted` is `true`. */
  isActive?: boolean;
  /** When `true`, the Active switch renders disabled while a pause/resume request is in flight. Defaults to `false`. */
  isActiveUpdating?: boolean;
  /** When `true`, the Active switch renders disabled (e.g. a completed one-time schedule that cannot be resumed), independent of `isActiveUpdating`. Defaults to `false`. */
  isActiveDisabled?: boolean;
  /** Called with the newly requested value when the user toggles the Active switch. The component performs no network call or optimistic update itself. */
  onActiveChange?: (nextActive: boolean) => void;
  /** Task title shown in the header and used as the page's accessible name. */
  displayName: string;
  /** When `true`, the entire body (Details, Configuration, and History) shows a page-level spinner instead of the fields below. Defaults to `false`. */
  isLoading?: boolean;
  /** When set, the entire body (Details, Configuration, and History) shows an error message and retry action instead of the fields below. */
  error?: Error | null;
  /** Called when the user activates the retry action shown alongside `error`. */
  onRetry?: () => void;
  /** Task description. Omit to hide the field. */
  description?: string;
  /** Resolved "Model or Agent" display value (already resolved to a display name, or the raw id as a fallback). */
  modelLabel?: string;
  /** Pre-formatted recurrence label, e.g. "Every Monday 12:00". */
  repeatsLabel?: string;
  /** Pre-formatted activity-window label, e.g. "Aug 1, 2026 – Dec 31, 2026". Omit to hide (unbounded or one-shot schedule). */
  activeWindowLabel?: string;
  /** Raw instructions markdown, passed to `renderInstructions` when supplied, or rendered via the default `MDMessageViewer` otherwise. Omit to hide the field entirely. */
  instructionsMarkdown?: string;
  /** Renders `instructionsMarkdown` as a ReactNode. When omitted, `instructionsMarkdown` is rendered via `MDMessageViewer` (the same markdown stack chat assistant messages use). */
  renderInstructions?: (markdown: string) => ReactNode;
  /** Pre-formatted "Next run" label shown under the History title, e.g. "Next run: Jul 31 at 9:00 AM". Omit to hide (e.g. when the schedule is paused or inactive). */
  nextRunLabel?: string;
  /** Runs to render in the History panel, in the order they should display (server order, newest first). */
  runs: ScheduledTaskRunItem[];
  /** When `true` and `runs` is empty, the History panel shows a loading state (skeleton rows) instead of `historyEmptyLabel`. Defaults to `false`. */
  runsIsLoading?: boolean;
  /** When `true`, `runsSkeletonCount` placeholder rows render below the loaded runs while the next page is fetched. Defaults to `false`. */
  runsIsLoadingMore?: boolean;
  /** Number of placeholder rows shown during initial load and load-more. Defaults to `6`. */
  runsSkeletonCount?: number;
  /** When set, the History panel shows an error message and retry action instead of `runs`. */
  runsError?: Error | null;
  /** Called when the user activates the History retry action shown alongside `runsError`. */
  onRunsRetry?: () => void;
  /** Whether another page of `runs` is available beyond what has been loaded so far. Defaults to `false`. */
  runsHasMore?: boolean;
  /** Called when the user activates the "Show more" button, rendered below the loaded runs while `runsHasMore` is `true`. Omit to hide the button entirely. */
  onRunsLoadMore?: () => void;
  /** Called with the run when the user clicks a row whose `conversationId` is set. Rows without a `conversationId` never invoke this, regardless of whether it is supplied. */
  onRunClick?: (run: ScheduledTaskRunItem) => void;
  /** Style overrides. */
  styles?: ScheduledTaskDetailViewStyles;
}

export interface ScheduledTaskDetailViewLabels {
  /** Accessible label for the back-navigation control. */
  backAriaLabel: string;
  /** Label for the header's Edit action. Shown only when `onEdit` is supplied. */
  editButtonLabel: string;
  /** Label for the header's destructive Delete action. Shown only when `onDelete` is supplied. */
  deleteButtonLabel: string;
  /** Label of the read-only indicator shown next to the title when `isDeleted` is `true`. */
  deletedStateLabel: string;
  /** Message shown alongside the page-level retry action when `error` is set. */
  errorLabel: string;
  /** Title of the Details section. */
  detailsTitle: string;
  /** Label for the description field. */
  descriptionLabel: string;
  /** Label for the model/agent field. */
  modelLabel: string;
  /** Label for the recurrence field, e.g. "Repeats". */
  repeatsLabel: string;
  /** Label for the activity-window field, e.g. "Active". Shown only for a recurring task whose window is bounded. */
  activeWindowLabel: string;
  /** Accessible name and visible label of the header's Active switch. Distinct from `activeWindowLabel`, which describes the cron activity date window. Shown only when `isActive` is defined. */
  activeStatusLabel: string;
  /** Announced via `aria-live` after a pause/resume mutation completes, separate from the switch's own accessible name. Empty string announces nothing. */
  activeStatusAnnouncement?: string;
