export interface ScheduledTaskDetailViewTypography {
  /** CSS class applied to the header title. Defaults to `'dial-h2-text'`. */
  titleClassName?: string;
  /** CSS class applied to section titles. Defaults to `'dial-body-semi-text'`. */
  sectionTitleClassName?: string;
  /** CSS class applied to field labels. Defaults to `'dial-tiny-text'`. */
  fieldLabelClassName?: string;
  /** CSS class applied to field values. Defaults to `'dial-small-text'`. */
  fieldValueClassName?: string;
  /** CSS class applied to each run row's timestamp text. Defaults to `'dial-small-text'`. */
  runTimestampClassName?: string;
}

export interface ScheduledTaskRunItem {
  /** Stable identifier for this run. */
  id: string;
  /** Outcome of this run, driving the row's status icon. */
  status: ScheduledTaskRunStatus;
  /** Pre-formatted timestamp, optionally including a duration suffix, e.g. `"today at 9:01 AM (99s)"`. */
  timestampLabel: string;
  /** Id of the conversation this run produced, when one exists. When set together with `onRunClick`, the row renders as interactive. */
  conversationId?: string;
  /** Whether this run's conversation is unread. When `true`, the row renders the unread-dot indicator. Defaults to `false`. */
  isUnread?: boolean;
}

export enum ScheduledTaskRunStatus {
  /** The run completed successfully. */
  Success = 'success',
  /** The run failed. */
  Error = 'error',
  /** The run is currently executing. */
  InProgress = 'inProgress',
  /** The scheduled run never started (e.g. the schedule was paused or the runner was unavailable). */
  Missed = 'missed',
}

ScheduledTaskRunHistoryList: FC<
  ScheduledTaskRunHistoryListProps
> = ({
  items,
  isLoading = false,
  isLoadingMore = false,
  skeletonCount = 6,
  error,
  onRetry,
  currentRunId,
  onRunClick,
  labels,
  footer,
  styles: listStyles,
}) => {
  const { colors, typography } = listStyles ?? {};
  const runTimestampClassName =
    typography?.runTimestampClassName ?? 'dial-small-text';
  const subtitleClassName = typography?.subtitleClassName ?? 'dial-body-text';
  const unreadIndicatorLabel = labels.unreadIndicatorLabel ?? 'Unread';

  const cssVars = buildCssVars({
    '--strhl-success-icon': colors?.successIconColor,
    '--strhl-error-icon': colors?.errorIconColor,
    '--strhl-missed-icon': colors?.missedIconColor,
    '--strhl-subtitle-text': colors?.subtitleTextColor,
    '--strhl-current-run-bg': colors?.currentRunBackground,
    '--strhl-unread-dot': colors?.unreadDotColor,
  });

  const renderRow = (run: ScheduledTaskRunItem) => {
    const statusLabel = labels.runStatusLabels[run.status];
    const isCurrent = run.id === currentRunId;
    /*
     * The row's own aria-label overrides all descendant text per the ARIA
     * accessible-name algorithm, so the unread state must be folded in here
     * rather than left as a nested sr-only span the label would otherwise
     * swallow — the same reason currentRunLabel is appended this way.
     */
    const accessibleNameSuffixes = [
      run.isUnread ? unreadIndicatorLabel : undefined,
      isCurrent ? labels.currentRunLabel : undefined,
    ].filter((suffix): suffix is string => Boolean(suffix));
    const accessibleName = [
      `${statusLabel} ${run.timestampLabel}`,
      ...accessibleNameSuffixes,
    ].join(' — ');
    /*
     * A row is only ever interactive when its own run produced a
     * conversation — an older/missed/in-progress run with no
     * `conversationId` always renders static, even if the host supplies
     * `onRunClick` unconditionally for the whole list.
     */
    const isClickable = Boolean(run.conversationId) && Boolean(onRunClick);

    return (
      <li
        key={run.id}
        {...(isClickable
          ? {
              role: 'button',
              tabIndex: 0,
              onClick: () => onRunClick?.(run),
              onKeyDown: (event: KeyboardEvent) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  onRunClick?.(run);
                }
              },
            }
          : {})}
        aria-label={accessibleName}
        aria-current={isCurrent ? 'true' : undefined}
        className={mergeClasses(
          'flex h-8 max-w-[328px] items-center justify-between gap-2 rounded-full pe-2 ps-0 desktop:ps-5',
          isCurrent && styles.currentRun,
          isClickable && 'cursor-pointer',
        )}
      >
        <span className="flex items-center gap-2 truncate">
          {/*
           * A fixed 12x12 slot is always reserved before the timestamp so its
           * horizontal position stays identical across rows whether or not
           * the unread dot itself is rendered.
           */}
          <span className="relative flex size-3 shrink-0 items-center justify-center">
            {run.isUnread && (
              <span
                className={mergeClasses(
                  'size-[5.33px] rounded-full',
                  styles.unreadDot,
                )}
                aria-hidden
              />
            )}
          </span>
          <span className={mergeClasses(runTimestampClassName, 'truncate')}>
            {run.timestampLabel}
          </span>
        </span>
        <span className="flex h-8 w-14 shrink-0 items-center justify-end">
          <RunStatusIcon status={run.status} />
        </span>
      </li>
    );
  };

  const renderSkeletons = (count: number) =>
    Array.from({ length: count }, (_, index) => (
      <li
        key={`history-skeleton-${index}`}
        aria-hidden="true"
        className="flex h-8 max-w-[328px] items-center justify-between gap-2 pe-2 ps-0 desktop:ps-5"
      >
        <Skeleton
          variant={SkeletonVariant.Rectangular}
          width="160px"
          height="16px"
        />
        <Skeleton
          variant={SkeletonVariant.Rectangular}
          width="16px"
          height="16px"
          className="shrink-0 rounded-full"
        />
      </li>
    ));

  if (isLoading && items.length === 0) {
    return (
      <ul
        style={cssVars}
        aria-label={labels.historyTitle}
        className="flex flex-col gap-0.5"
      >
        {renderSkeletons(skeletonCount)}
      </ul>
    );
  }

  if (error && items.length === 0) {
    return (
      <div style={cssVars} className="flex flex-col items-start gap-3">
        <p
          role="alert"
          className={mergeClasses(subtitleClassName, styles.subtitleText)}
        >
          {labels.errorLabel}
        </p>
        <GhostButton label={labels.retryLabel} onClick={onRetry} />
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <div
        style={cssVars}
        className="flex w-full flex-col items-center justify-center gap-2 py-4"
      >
        <IconClipboardX
          size={44}
          stroke={DIAL_KIT_ICON_STROKE}
          className={styles.subtitleText}
          aria-hidden
        />
        <p role="status" className={runTimestampClassName}>
          {labels.emptyLabel}
        </p>
      </div>
    );
  }

  return (
    <ul
      style={cssVars}
      aria-label={labels.historyTitle}
      className="flex flex-col gap-0.5"
    >
      {items.map(renderRow)}
      {isLoadingMore && renderSkeletons(skeletonCount)}
      {error ? (
        <li className="flex flex-col items-start gap-3 px-5 py-2">
          <p
            role="alert"
            className={mergeClasses(subtitleClassName, styles.subtitleText)}
          >
            {labels.errorLabel}
          </p>
          <GhostButton label={labels.retryLabel} onClick={onRetry} />
        </li>
      ) : (
        footer
      )}
    </ul>
  );
}

export interface ScheduledTaskRunHistoryListProps {
  /** Runs to render, in the order they should display (server order, newest first). */
  items: ScheduledTaskRunItem[];
  /** When `true` and `items` is empty, shows `skeletonCount` placeholder rows instead of `labels.emptyLabel`. Defaults to `false`. */
  isLoading?: boolean;
  /** When `true`, `skeletonCount` placeholder rows render below the loaded rows. Defaults to `false`. */
  isLoadingMore?: boolean;
  /** Number of placeholder rows shown during `isLoading`/`isLoadingMore`. Defaults to `6`. */
  skeletonCount?: number;
  /** When set, shows an error message and retry action instead of `items`. */
  error?: Error | null;
  /** Called when the user activates the retry action shown alongside `error`. */
  onRetry?: () => void;
  /** The `id` of the run to render with the current-run visual and accessible treatment. Omit to mark no row as current. */
  currentRunId?: string;
  /** Called with the run when the user clicks a row whose `conversationId` is set. Rows without a `conversationId` never invoke this, regardless of whether it is supplied. */
  onRunClick?: (run: ScheduledTaskRunItem) => void;
  /** Localized labels. */
  labels: ScheduledTaskRunHistoryListLabels;
  /**
   * Rendered after the loaded rows (and any load-more skeletons). Hosts supply
   * their own pagination trigger here — a scroll sentinel, a "Show more"
   * button, or nothing — the component has no built-in pagination mechanism.
   */
  footer?: ReactNode;
  /** Style overrides. */
  styles?: ScheduledTaskRunHistoryListStyles;
}

export interface ScheduledTaskRunHistoryListLabels {
  /** Accessible label applied to the row list, e.g. "History". */
  historyTitle: string;
  /** Message shown when `items` is empty and `isLoading` is `false`. */
  emptyLabel: string;
  /** Message shown alongside the retry action when `error` is set. */
  errorLabel: string;
  /** Label for the retry action shown alongside `error`. */
  retryLabel: string;
  /** Per-status label used to build each run row's accessible name, e.g. `{ success: 'Succeeded', ... }`. */
  runStatusLabels: Record<ScheduledTaskRunStatus, string>;
  /** Appended to the current run row's accessible name, e.g. "Current run". Omit to skip the accessible current-run suffix. */
  currentRunLabel?: string;
  /** `sr-only` label announced alongside the unread-dot indicator on a row whose `isUnread` is `true`. Defaults to `'Unread'`. */
  unreadIndicatorLabel?: string;
}

export interface ScheduledTaskRunHistoryListStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: ScheduledTaskRunHistoryListColors;
  /** Typography class overrides. */
  typography?: ScheduledTaskRunHistoryListTypography;
}

export interface ScheduledTaskRunHistoryListColors {
  /** Success status icon color. Fallback: `--text-success`. */
  successIconColor?: string;
  /** Error status icon color. Fallback: `--text-error`. */
  errorIconColor?: string;
  /** Missed status icon color. Fallback: `--text-secondary`. */
  missedIconColor?: string;
  /** Error/empty message text color. Fallback: `--text-secondary`. */
  subtitleTextColor?: string;
  /** Current-run row background. Fallback: `--bg-control-accent-alpha-active`. */
  currentRunBackground?: string;
  /** Unread-dot indicator fill color. Fallback: `--text-accent`. */
  unreadDotColor?: string;
}

export interface ScheduledTaskRunHistoryListTypography {
  /** CSS class applied to each run row's timestamp text. Defaults to `'dial-small-text'`. */
  runTimestampClassName?: string;
  /** CSS class applied to the error and empty-state messages. Defaults to `'dial-body-text'`. */
  subtitleClassName?: string;
}

ScheduledTaskDetailsSummary: FC<
  ScheduledTaskDetailsSummaryProps
> = ({
  modelLabel,
  instructionsLabel,
  modelDisplayName,
  instructionsMarkdown,
  renderInstructions,
  styles,
}) => {
  const fieldLabelClassName =
    styles?.typography?.fieldLabelClassName ?? 'dial-tiny-text';
  const fieldValueClassName =
    styles?.typography?.fieldValueClassName ?? 'dial-body-text';

  const renderInstructionsContent = (markdown: string) =>
    renderInstructions ? (
      renderInstructions(markdown)
    ) : (
      <MDMessageViewer content={markdown} />
    );

  return (
    <div className="flex flex-col gap-3">
      {modelDisplayName && (
        <div className="flex flex-col gap-2">
          <span className={fieldLabelClassName}>{modelLabel}</span>
          <p className={fieldValueClassName}>{modelDisplayName}</p>
        </div>
      )}

      {instructionsMarkdown && (
        <div className="flex flex-col gap-2">
          <span className={fieldLabelClassName}>{instructionsLabel}</span>
          {renderInstructionsContent(instructionsMarkdown)}
        </div>
      )}
    </div>
  );
}

export interface ScheduledTaskDetailsSummaryProps {
  /** Label for the model field, e.g. "Model". */
  modelLabel: string;
  /** Label for the instructions field, e.g. "Instructions". */
  instructionsLabel: string;
  /** Resolved "Model" display value (already resolved to a display name, or the raw id as a fallback). Omit to hide the field. */
  modelDisplayName?: string;
  /** Raw instructions markdown, passed to `renderInstructions` when supplied, or rendered via the default `MDMessageViewer` otherwise. Omit to hide the field entirely. */
