ScheduledTaskCreateForm: FC<ScheduledTaskCreateFormProps> = ({
  labels,
  values,
  errors,
  modelSelector,
  modelLabelId,
  onFieldChange,
  onBack,
  onCancel,
  onSubmit,
  isSubmitting = false,
  markdownEditorTheme,
  styles: formStyles,
}) => {
  const instructionsEditorId = useId();
  const instructionsCapRef = useAvailableHeightCap<HTMLDivElement>();
  const [timeBlurError, setTimeBlurError] = useState<string>();
  const { colors, typography } = formStyles ?? {};
  const titleClassName = typography?.titleClassName ?? 'dial-h1-text';
  const sectionTitleClassName =
    typography?.sectionTitleClassName ?? 'dial-body-semi-text';
  const sectionSubtitleClassName =
    typography?.sectionSubtitleClassName ?? 'dial-tiny-text';
  const instructionsLabelClassName =
    typography?.instructionsLabelClassName ?? 'dial-body-semi-text mb-1';
  const instructionsErrorClassName =
    typography?.instructionsErrorClassName ?? 'dial-small-text';
  const cssVars = buildCssVars({
    '--stcf-details-border': colors?.detailsColumnBorder,
    '--stcf-subtitle-text': colors?.sectionSubtitleText,
    '--stcf-error-text': colors?.instructionsErrorText,
  });

  /*
   * The masked time input only reports complete `HH:mm` values through
   * onChange, so a cleared or half-typed draft never reaches `values.time` —
   * the blur pass below validates the visible draft instead.
   */
  const handleTimeBlur: FocusEventHandler<HTMLInputElement> = (event) => {
    const errorLabel = TIME_OF_DAY_PATTERN.test(event.target.value)
      ? undefined
      : labels.timeInvalidLabel;

    setTimeBlurError(errorLabel);
    onFieldChange('time', event.target.value);
  };

  const handleTimeChange = (value: CalendarValue) => {
    setTimeBlurError(undefined);
    onFieldChange('time', typeof value === 'string' ? value : '');
  };

  const isTimeFieldShown =
    values.repeat !== ScheduledTaskRepeat.OneTime &&
    values.repeat !== ScheduledTaskRepeat.Hourly;

  /*
   * A blur error describes the time field's visible draft. When a repeat
   * switch hides the field, that draft is gone — reset the error so a
   * later switch back cannot re-show a stale error under the (valid)
   * controlled value and silently block Save.
   */
  useEffect(() => {
    if (!isTimeFieldShown) {
      setTimeBlurError(undefined);
    }
  }, [isTimeFieldShown]);

  const timeError = isTimeFieldShown
    ? (timeBlurError ?? errors.time)
    : undefined;

  const handleRunAtChange = (value: string) => onFieldChange('runAt', value);

  const isCreateDisabled =
    isSubmitting ||
    !values.displayName.trim() ||
    !values.modelId ||
    !values.prompt.trim() ||
    /* An empty shown time blocks Save immediately, like the other required
     * fields — the blur error alone would only catch it on blur or submit. */
    (isTimeFieldShown && !values.time) ||
    Boolean(timeError);

  return (
    <BuilderFormContainer
      labels={{
        title: labels.pageTitle,
        backButtonLabel: labels.backButtonLabel,
        cancelButtonLabel: labels.cancelButtonLabel,
        submitButtonLabel: labels.createButtonLabel,
        submittingLabel: labels.submittingLabel ?? 'Saving',
      }}
      onBack={onBack}
      onCancel={onCancel}
      onSubmit={onSubmit}
      isCancelDisabled={isSubmitting}
      isSubmitDisabled={isCreateDisabled}
      isSubmitting={isSubmitting}
      styles={{
        colors: { background: colors?.background },
        header: {
          colors: { borderColor: colors?.headerBorder },
          typography: { fontClassName: titleClassName },
        },
        cssVars,
      }}
      left={
        <div
          role="group"
          aria-label={labels.detailsSectionTitle}
          className={mergeClasses(
            'flex flex-1 flex-col gap-5 border-e px-4 py-6 desktop:px-8',
            styles.detailsColumn,
          )}
        >
          <div className="flex flex-col gap-1">
            <h2 className={sectionTitleClassName}>
              {labels.detailsSectionTitle}
            </h2>
            <p
              className={mergeClasses(
                sectionSubtitleClassName,
                styles.sectionSubtitle,
              )}
            >
              {labels.detailsSectionSubtitle}
            </p>
          </div>

          <Input
            id="scheduled-task-display-name"
            value={values.displayName}
            onChange={(value) => onFieldChange('displayName', value ?? '')}
            labelProps={{ label: labels.displayNameLabel, required: true }}
            invalid={Boolean(errors.displayName)}
            error={errors.displayName}
          />

          <Textarea
            id="scheduled-task-description"
            value={values.description ?? ''}
            onChange={(value) => onFieldChange('description', value)}
            labelProps={{ label: labels.descriptionLabel }}
            maxLength={DESCRIPTION_MAX_LENGTH}
            invalid={Boolean(errors.description)}
            error={errors.description}
            caption={
              values.description
                ? `${values.description.length}/${DESCRIPTION_MAX_LENGTH}`
                : undefined
            }
          />

          <div className="flex flex-col gap-1">
            <Label
              id={modelLabelId}
              label={labels.modelOrAgentLabel}
              required
            />
            {modelSelector}
            {errors.modelId && (
              <p
                className={mergeClasses(
                  instructionsErrorClassName,
                  styles.instructionsError,
                )}
              >
                {errors.modelId}
              </p>
            )}
          </div>

          <div className="flex flex-col gap-3">
            <Select
              labelProps={{ label: labels.repeatLabel }}
              value={values.repeat}
              onChange={(next) =>
                onFieldChange('repeat', next as ScheduledTaskRepeat)
              }
              options={labels.repeatOptions.map((option) => ({
                value: option.key,
                label: option.label,
              }))}
            />

            {values.repeat === ScheduledTaskRepeat.OneTime && (
              <ScheduledTaskRunAtField
                label={labels.runAtLabel}
                value={values.runAt ?? ''}
                onChange={handleRunAtChange}
                error={errors.runAt}
                errorClassName={instructionsErrorClassName}
              />
            )}

            {values.repeat !== ScheduledTaskRepeat.OneTime && (
              <>
                {isTimeFieldShown && (
                  <div className="flex flex-col gap-1">
                    <Calendar
                      id="scheduled-task-time"
                      mode={CalendarMode.Time}
                      value={values.time}
                      onChange={handleTimeChange}
                      onBlur={handleTimeBlur}
                      labelProps={{ label: labels.timeLabel, required: true }}
                      invalid={Boolean(timeError)}
                      disabled={isSubmitting}
                      showTimezone
                    />
                    {timeError && (
                      <p
                        className={mergeClasses(
                          instructionsErrorClassName,
                          styles.instructionsError,
                        )}
                      >
                        {timeError}
                      </p>
                    )}
                  </div>
                )}
                {values.repeat === ScheduledTaskRepeat.Weekly && (
                  <div className="flex flex-col gap-1">
                    <Calendar
                      id="scheduled-task-day-of-week"
                      mode={CalendarMode.Weekday}
                      value={dayOfWeekToCalendarValue(values.dayOfWeek)}
                      onChange={(value) =>
                        onFieldChange(
                          'dayOfWeek',
                          calendarValueToDayOfWeek(value),
                        )
                      }
                      labelProps={{
                        label: labels.dayOfWeekLabel,
                        required: true,
                      }}
                      invalid={Boolean(errors.dayOfWeek)}
                    />
                    {errors.dayOfWeek && (
                      <p
                        className={mergeClasses(
                          instructionsErrorClassName,
                          styles.instructionsError,
                        )}
                      >
                        {errors.dayOfWeek}
                      </p>
                    )}
                  </div>
                )}
                {values.repeat === ScheduledTaskRepeat.Monthly && (
                  <Input
                    id="scheduled-task-day-of-month"
                    value={values.dayOfMonth ?? ''}
                    onChange={(value) =>
                      onFieldChange('dayOfMonth', value ?? '')
                    }
                    labelProps={{
                      label: labels.dayOfMonthLabel,
                      required: true,
                    }}
                    invalid={Boolean(errors.dayOfMonth)}
                    error={errors.dayOfMonth}
                  />
                )}
                {values.repeat === ScheduledTaskRepeat.Hourly && (
                  <NumberInput
                    id="scheduled-task-minute"
                    integer
                    min={0}
                    max={59}
                    value={values.minute ?? ''}
                    onChange={(value) =>
                      onFieldChange(
                        'minute',
                        value != null ? String(value) : '',
                      )
                    }
                    labelProps={{
                      label: labels.minuteLabel,
                      required: true,
                    }}
                    invalid={Boolean(errors.minute)}
                    error={errors.minute}
                  />
                )}
                {/* The two date fields always share one row. */}
                <div className="flex flex-row gap-3">
                  <div className="flex flex-1 flex-col gap-1">
                    <Calendar
                      id="scheduled-task-start-date"
                      mode={CalendarMode.Date}
                      value={dateValueToCalendarValue(values.startDate)}
                      onChange={(value) =>
                        onFieldChange(
                          'startDate',
                          calendarValueToDateValue(value),
                        )
                      }
                      labelProps={{ label: labels.startDateLabel }}
                      placeholder={labels.startDatePlaceholder}
                      invalid={Boolean(errors.startDate)}
                    />
                    {errors.startDate && (
                      <p
                        className={mergeClasses(
                          instructionsErrorClassName,
                          styles.instructionsError,
                        )}
                      >
                        {errors.startDate}
                      </p>
                    )}
                  </div>

                  <div className="flex flex-1 flex-col gap-1">
                    <Calendar
                      id="scheduled-task-end-date"
                      mode={CalendarMode.Date}
                      value={dateValueToCalendarValue(values.endDate)}
                      onChange={(value) =>
                        onFieldChange(
                          'endDate',
                          calendarValueToDateValue(value),
                        )
                      }
                      labelProps={{ label: labels.endDateLabel }}
                      placeholder={labels.endDatePlaceholder}
                      invalid={Boolean(errors.endDate)}
                    />
                    {errors.endDate && (
                      <p
                        className={mergeClasses(
                          instructionsErrorClassName,
                          styles.instructionsError,
                        )}
                      >
                        {errors.endDate}
                      </p>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      }
    >
      <div
        role="group"
        aria-label={labels.configurationSectionTitle}
        className="flex flex-1 flex-col gap-5 px-4 py-6 desktop:px-8"
      >
        <div className="flex flex-col gap-1">
          <h2 className={sectionTitleClassName}>
            {labels.configurationSectionTitle}
          </h2>
          <p
            className={mergeClasses(
              sectionSubtitleClassName,
              styles.sectionSubtitle,
            )}
          >
            {labels.configurationSectionSubtitle}
          </p>
        </div>

        <div className="flex flex-1 flex-col gap-1">
          {/*
           * A real <label for>, not a span: the markdown editor renders a plain
           * textarea, and text sitting next to it names nothing the browser
           * associates with the control.
           */}
          <label
            htmlFor={instructionsEditorId}
            className={instructionsLabelClassName}
          >
            {labels.instructionsLabel}
          </label>
          <div
            ref={instructionsCapRef}
            className={mergeClasses(
              'w-full max-w-[996px]',
              MARKDOWN_EDITOR_MAX_HEIGHT_CLASS_NAME,
              MARKDOWN_EDITOR_PREVIEW_LIST_CLASS_NAME,
            )}
          >
            <Suspense fallback={<Spinner />}>
              <MarkdownEditor
                id={instructionsEditorId}
                value={values.prompt}
                onChange={(value) => onFieldChange('prompt', value)}
                height={480}
                theme={markdownEditorTheme}
              />
            </Suspense>
          </div>
          {errors.prompt && (
            <p
              className={mergeClasses(
                instructionsErrorClassName,
                styles.instructionsError,
              )}
            >
              {errors.prompt}
            </p>
          )}
        </div>
      </div>
    </BuilderFormContainer>
  );
}

ScheduledTaskDetailView: FC<ScheduledTaskDetailViewProps> = ({
  labels,
  onBack,
  onEdit,
  onDelete,
  isDeleting = false,
  isDeleted = false,
  isActive,
  isActiveUpdating = false,
  isActiveDisabled = false,
  onActiveChange,
  displayName,
  isLoading = false,
  error,
  onRetry,
  description,
  modelLabel,
  repeatsLabel,
  activeWindowLabel,
  nextRunLabel,
  instructionsMarkdown,
  renderInstructions,
  runs,
  runsIsLoading = false,
  runsIsLoadingMore = false,
  runsSkeletonCount = 6,
  runsError,
  onRunsRetry,
  runsHasMore = false,
  onRunsLoadMore,
  onRunClick,
  styles: viewStyles,
}) => {
  const { colors, typography } = viewStyles ?? {};
  const titleClassName = typography?.titleClassName ?? 'dial-h2-text';
  const sectionTitleClassName =
    typography?.sectionTitleClassName ?? 'dial-body-semi-text';
  const fieldLabelClassName =
    typography?.fieldLabelClassName ?? 'dial-tiny-text';
  const fieldValueClassName =
    typography?.fieldValueClassName ?? 'dial-small-text';
  const runTimestampClassName =
    typography?.runTimestampClassName ?? 'dial-small-text';

  const cssVars = buildCssVars({
    '--stdv-bg': colors?.background,
    '--stdv-header-border': colors?.headerBorder,
    '--stdv-details-border': colors?.detailsColumnBorder,
    '--stdv-subtitle-text': colors?.subtitleText,
    '--stdv-history-bg': colors?.historyCardBackground,
  });

  const isMobile = useIsMobile();
  /*
   * Keyed as a plain string so the kit's `onTabChange(tabId: string)` maps
   * straight onto the state setter; the only ids ever stored are the
   * `ScheduledTaskDetailTab` values. Held here — not under the mobile-only
   * branch — so the selection survives a viewport resize across the
   * breakpoint instead of resetting.
   */
  const [activeTabId, setActiveTabId] = useState<string>(
    ScheduledTaskDetailTab.Details,
  );

  const detailTabs: TabItem[] = [
    { id: ScheduledTaskDetailTab.Details, label: labels.detailsTitle },
    {
      id: ScheduledTaskDetailTab.Configuration,
      label: labels.configurationTitle,
    },
    { id: ScheduledTaskDetailTab.History, label: labels.historyTitle },
  ];
  const activeTabLabel =
    detailTabs.find((tab) => tab.id === activeTabId)?.label ??
    labels.detailsTitle;

  /*
   * The section elements are built once and composed by whichever layout the
   * current viewport mounts, so section content cannot drift between the
   * mobile/tab and desktop/column presentations. Only the History section
   * differs by context (card vs flow chrome), so it's a builder.
   */
  const detailsSection = (
    <ScheduledTaskDetailsSection
      labels={{
        descriptionLabel: labels.descriptionLabel,
        modelLabel: labels.modelLabel,
        repeatsLabel: labels.repeatsLabel,
        activeWindowLabel: labels.activeWindowLabel,
      }}
      description={description}
      modelLabel={modelLabel}
      repeatsLabel={repeatsLabel}
      activeWindowLabel={activeWindowLabel}
      fieldLabelClassName={fieldLabelClassName}
      fieldValueClassName={fieldValueClassName}
    />
  );

  const configurationSection = (
    <ScheduledTaskConfigurationSection
      instructionsLabel={labels.instructionsLabel}
      instructionsMarkdown={instructionsMarkdown}
      renderInstructions={renderInstructions}
      fieldLabelClassName={fieldLabelClassName}
    />
  );

  const buildHistorySection = (
    variant: ScheduledTaskHistorySectionVariant,
  ): ReactNode => (
    <ScheduledTaskHistorySection
      variant={variant}
      labels={{
        historyTitle: labels.historyTitle,
        historyEmptyLabel: labels.historyEmptyLabel,
        historyErrorLabel: labels.historyErrorLabel,
        historyRetryLabel: labels.historyRetryLabel,
        historyLoadingMoreLabel: labels.historyLoadingMoreLabel,
        historyShowMoreLabel: labels.historyShowMoreLabel,
        runStatusLabels: labels.runStatusLabels,
        unreadIndicatorLabel: labels.unreadIndicatorLabel,
      }}
      nextRunLabel={nextRunLabel}
      items={runs}
      isLoading={runsIsLoading}
      isLoadingMore={runsIsLoadingMore}
      skeletonCount={runsSkeletonCount}
      error={runsError}
      onRetry={onRunsRetry}
      hasMore={runsHasMore}
      onLoadMore={onRunsLoadMore}
      onRunClick={onRunClick}
      runTimestampClassName={runTimestampClassName}
      sectionTitleClassName={sectionTitleClassName}
      colors={colors}
    />
  );

  /*
   * Exactly one panel renders at a time. The tab row replaces the section
   * titles below the desktop breakpoint, so the panels carry no headings of
   * their own — the tab is the section's accessible name.
   */
  const renderActiveTabPanel = (): ReactNode => {
    if (activeTabId === ScheduledTaskDetailTab.Configuration) {
      return configurationSection;
    }
    if (activeTabId === ScheduledTaskDetailTab.History) {
      return buildHistorySection(ScheduledTaskHistorySectionVariant.Flow);
    }
    return detailsSection;
  };

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'flex h-full w-full flex-col overflow-y-auto',
        styles.container,
      )}
    >
      <div
        className={mergeClasses(
          'flex h-16 shrink-0 items-center justify-between gap-2 border-t px-8 desktop:border-b desktop:border-t-0',
          styles.header,
        )}
      >
        <div className="flex min-w-0 items-center gap-2">
          <GhostIconButton
            icon={
              <IconArrowLeft
                size={DIAL_ICON_SIZE.LG}
                className="rtl:scale-x-[-1]"
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
            }
            aria-label={labels.backAriaLabel}
            onClick={onBack}
          />
          {/*
           * Hidden below the desktop breakpoint, where the standalone title
           * row after the header renders its own copy — exactly one copy of
           * the title is visible at any width.
           */}
          <h1
            className={mergeClasses(
              'hidden truncate desktop:block',
              titleClassName,
            )}
          >
            {displayName}
          </h1>
          {isDeleted && (
            <span
              className={mergeClasses(
                'hidden shrink-0 desktop:inline',
                fieldValueClassName,
                styles.subtitleText,
              )}
            >
              {labels.deletedStateLabel}
            </span>
          )}
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {!isDeleted && isActive !== undefined && (
            <Switch
              id="scheduled-task-active-switch"
              labelProps={{ label: labels.activeStatusLabel }}
              isOn={isActive}
              disabled={isActiveUpdating || isActiveDisabled || isDeleting}
              onChange={(value) => onActiveChange?.(value)}
            />
          )}

          {!isDeleted && onDelete && (
            <GhostButton
              variant={ButtonVariant.Danger}
              label={labels.deleteButtonLabel}
              iconBefore={
                <IconTrashX
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              onClick={onDelete}
              disabled={isDeleting}
              className="shrink-0"
            />
          )}

          {!isDeleted && onEdit && (
            <NeutralButton
              label={labels.editButtonLabel}
              iconBefore={
                <IconPencilMinus
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              onClick={onEdit}
              disabled={isDeleting}
              className="shrink-0"
            />
          )}
        </div>
      </div>

      {/*
       * Standalone title row, visible only below the desktop breakpoint
       * (mobile and tablet), where the in-header title is hidden — exactly
       * one copy of the title is visible at any width.
       */}
      <div className="flex min-w-0 items-center gap-2 px-8 py-3 desktop:hidden">
        <h1 className={mergeClasses('truncate', titleClassName)}>
          {displayName}
        </h1>
        {isDeleted && (
          <span
            className={mergeClasses(
              'shrink-0',
              fieldValueClassName,
              styles.subtitleText,
            )}
          >
            {labels.deletedStateLabel}
          </span>
        )}
      </div>

      {labels.activeStatusAnnouncement != null && (
        <span role="status" aria-live="polite" className="sr-only">
          {labels.activeStatusAnnouncement}
        </span>
      )}

      {isLoading && (
        <div className="flex flex-1 items-center justify-center">
          <Spinner />
        </div>
      )}

      {!isLoading && error && (
        <div className="flex flex-1 flex-col items-center justify-center gap-3">
          <p className={mergeClasses(fieldValueClassName, styles.subtitleText)}>
            {labels.errorLabel}
          </p>
          <GhostButton label={labels.retryLabel} onClick={onRetry} />
        </div>
      )}

      {!isLoading &&
        !error &&
        (isMobile ? (
          <div className="flex flex-1 flex-col">
            <Tabs
              ariaLabel={labels.tabsAriaLabel ?? 'Scheduled task sections'}
              className="px-8"
              tabs={detailTabs}
              activeTabId={activeTabId}
              onTabChange={setActiveTabId}
            />
            {/*
             * One panel renders at a time. Its accessible name comes from the
             * active tab's label — the kit's tab elements expose no
             * referenceable ids for `aria-labelledby`.
             */}
            <div
              role="tabpanel"
              aria-label={activeTabLabel}
              className="flex flex-1 flex-col gap-5 px-8 py-6"
            >
              {renderActiveTabPanel()}
            </div>
          </div>
        ) : (
          <div className="flex flex-1 flex-col desktop:flex-row">
            <div
              role="group"
              aria-label={labels.detailsTitle}
              className={mergeClasses(
                'flex w-full flex-col gap-5 border-e px-8 py-6 desktop:w-[360px] desktop:shrink-0',
                styles.detailsColumn,
              )}
            >
              <h2 className={sectionTitleClassName}>{labels.detailsTitle}</h2>
              {detailsSection}
            </div>

            <div className="flex w-full min-w-0 flex-1 flex-col gap-5 px-8 py-6">
              <h2 className={sectionTitleClassName}>
                {labels.configurationTitle}
              </h2>
              {configurationSection}
            </div>

            <div className="flex w-full justify-center p-6 desktop:w-auto desktop:items-start">
              {buildHistorySection(ScheduledTaskHistorySectionVariant.Card)}
            </div>
          </div>
        ))}
    </div>
  );
}

ScheduledTaskRunHistoryList: FC<
  ScheduledTaskRunHistoryListProps
> = ({
  items,
  isLoading = false,
  isLoadingMore = false,
  skeletonCount = 6,
  error,
  onRetry,
  currentRunId,
  onRunClick,
  labels,
  footer,
  styles: listStyles,
}) => {
  const { colors, typography } = listStyles ?? {};
  const runTimestampClassName =
    typography?.runTimestampClassName ?? 'dial-small-text';
  const subtitleClassName = typography?.subtitleClassName ?? 'dial-body-text';
  const unreadIndicatorLabel = labels.unreadIndicatorLabel ?? 'Unread';

  const cssVars = buildCssVars({
    '--strhl-success-icon': colors?.successIconColor,
    '--strhl-error-icon': colors?.errorIconColor,
    '--strhl-missed-icon': colors?.missedIconColor,
    '--strhl-subtitle-text': colors?.subtitleTextColor,
    '--strhl-current-run-bg': colors?.currentRunBackground,
    '--strhl-unread-dot': colors?.unreadDotColor,
  });

  const renderRow = (run: ScheduledTaskRunItem) => {
    const statusLabel = labels.runStatusLabels[run.status];
    const isCurrent = run.id === currentRunId;
    /*
     * The row's own aria-label overrides all descendant text per the ARIA
     * accessible-name algorithm, so the unread state must be folded in here
     * rather than left as a nested sr-only span the label would otherwise
     * swallow — the same reason currentRunLabel is appended this way.
     */
    const accessibleNameSuffixes = [
      run.isUnread ? unreadIndicatorLabel : undefined,
      isCurrent ? labels.currentRunLabel : undefined,
    ].filter((suffix): suffix is string => Boolean(suffix));
    const accessibleName = [
      `${statusLabel} ${run.timestampLabel}`,
      ...accessibleNameSuffixes,
    ].join(' — ');
    /*
     * A row is only ever interactive when its own run produced a
     * conversation — an older/missed/in-progress run with no
     * `conversationId` always renders static, even if the host supplies
     * `onRunClick` unconditionally for the whole list.
     */
    const isClickable = Boolean(run.conversationId) && Boolean(onRunClick);

    return (
      <li
        key={run.id}
        {...(isClickable
          ? {
              role: 'button',
              tabIndex: 0,
              onClick: () => onRunClick?.(run),
              onKeyDown: (event: KeyboardEvent) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  onRunClick?.(run);
                }
              },
            }
          : {})}
        aria-label={accessibleName}
        aria-current={isCurrent ? 'true' : undefined}
        className={mergeClasses(
          'flex h-8 max-w-[328px] items-center justify-between gap-2 rounded-full pe-2 ps-0 desktop:ps-5',
          isCurrent && styles.currentRun,
          isClickable && 'cursor-pointer',
        )}
      >
        <span className="flex items-center gap-2 truncate">
          {/*
           * A fixed 12x12 slot is always reserved before the timestamp so its
           * horizontal position stays identical across rows whether or not
           * the unread dot itself is rendered.
           */}
          <span className="relative flex size-3 shrink-0 items-center justify-center">
            {run.isUnread && (
              <span
                className={mergeClasses(
                  'size-[5.33px] rounded-full',
                  styles.unreadDot,
                )}
                aria-hidden
              />
            )}
          </span>
          <span className={mergeClasses(runTimestampClassName, 'truncate')}>
            {run.timestampLabel}
          </span>
        </span>
        <span className="flex h-8 w-14 shrink-0 items-center justify-end">
          <RunStatusIcon status={run.status} />
        </span>
      </li>
    );
  };

  const renderSkeletons = (count: number) =>
    Array.from({ length: count }, (_, index) => (
      <li
        key={`history-skeleton-${index}`}
        aria-hidden="true"
        className="flex h-8 max-w-[328px] items-center justify-between gap-2 pe-2 ps-0 desktop:ps-5"
      >
        <Skeleton
          variant={SkeletonVariant.Rectangular}
          width="160px"
          height="16px"
        />
        <Skeleton
          variant={SkeletonVariant.Rectangular}
          width="16px"
          height="16px"
          className="shrink-0 rounded-full"
        />
      </li>
    ));

  if (isLoading && items.length === 0) {
    return (
      <ul
        style={cssVars}
        aria-label={labels.historyTitle}
        className="flex flex-col gap-0.5"
      >
        {renderSkeletons(skeletonCount)}
      </ul>
    );
  }

  if (error && items.length === 0) {
    return (
      <div style={cssVars} className="flex flex-col items-start gap-3">
        <p
          role="alert"
          className={mergeClasses(subtitleClassName, styles.subtitleText)}
        >
          {labels.errorLabel}
        </p>
        <GhostButton label={labels.retryLabel} onClick={onRetry} />
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <div
        style={cssVars}
        className="flex w-full flex-col items-center justify-center gap-2 py-4"
      >
        <IconClipboardX
          size={44}
          stroke={DIAL_KIT_ICON_STROKE}
          className={styles.subtitleText}
          aria-hidden
        />
        <p role="status" className={runTimestampClassName}>
          {labels.emptyLabel}
        </p>
      </div>
    );
  }

  return (
    <ul
      style={cssVars}
      aria-label={labels.historyTitle}
      className="flex flex-col gap-0.5"
    >
      {items.map(renderRow)}
      {isLoadingMore && renderSkeletons(skeletonCount)}
      {error ? (
        <li className="flex flex-col items-start gap-3 px-5 py-2">
          <p
            role="alert"
            className={mergeClasses(subtitleClassName, styles.subtitleText)}
          >
            {labels.errorLabel}
          </p>
          <GhostButton label={labels.retryLabel} onClick={onRetry} />
        </li>
      ) : (
        footer
      )}
    </ul>
  );
}

ScheduledTaskDetailsSummary: FC<
  ScheduledTaskDetailsSummaryProps
> = ({
  modelLabel,
  instructionsLabel,
  modelDisplayName,
  instructionsMarkdown,
  renderInstructions,
  styles,
}) => {
  const fieldLabelClassName =
    styles?.typography?.fieldLabelClassName ?? 'dial-tiny-text';
  const fieldValueClassName =
    styles?.typography?.fieldValueClassName ?? 'dial-body-text';

  const renderInstructionsContent = (markdown: string) =>
    renderInstructions ? (
      renderInstructions(markdown)
    ) : (
      <MDMessageViewer content={markdown} />
    );

  return (
    <div className="flex flex-col gap-3">
      {modelDisplayName && (
        <div className="flex flex-col gap-2">
          <span className={fieldLabelClassName}>{modelLabel}</span>
          <p className={fieldValueClassName}>{modelDisplayName}</p>
        </div>
      )}

      {instructionsMarkdown && (
        <div className="flex flex-col gap-2">
          <span className={fieldLabelClassName}>{instructionsLabel}</span>
          {renderInstructionsContent(instructionsMarkdown)}
        </div>
      )}
    </div>
  );
}

